+	/**
+	 * Adds a `window` clause to the query.
+	 *
+	 * Calling this method will specify named windows that can be referenced by window functions.
+	 *
+	 * @param name the window name.
+	 * @param spec the window specification.
+	 */
+	window(
+		name: string,
+		spec:
+			| WindowSpec
+			| SQLWrapper
+			| string
+			| ((aliases: this['_']['selection']) => WindowSpec | SQLWrapper | string),
+	): this {
+		if (typeof name !== 'string' || name.length === 0) {
+			throw new Error('Window name must be a non-empty string');
+		}
+		if (name.trim().length === 0) {
+			throw new Error('Window name cannot be whitespace-only');
+		}
+
+		let resolvedSpec: WindowSpec | SQLWrapper | string;
+		if (typeof spec === 'function') {
+			resolvedSpec = spec(
+				new Proxy(
+					this.config.fields,
+					new SelectionProxyHandler({ sqlAliasedBehavior: 'alias', sqlBehavior: 'sql' }),
+				) as TSelection,
+			);
+		} else {
+			resolvedSpec = spec;
+		}
+
+		if (!this.config.windows) {
+			this.config.windows = [];
+		}
+		this.config.windows.push({ name, spec: resolvedSpec as any });
+		return this;
+	}
+
 	/**
 	 * Adds a `limit` clause to the query.
 	 *
